/**
 * Next.js 16 Cache Handler Types
 * Based on: https://nextjs.org/docs/app/api-reference/config/next-config-js/cacheHandler
 */

/**
 * Prefix for implicit tags generated by Next.js (system-generated tags for ISR)
 */
export const IMPLICIT_TAG_PREFIX = "_N_T_";

/**
 * Cache entry value types supported by Next.js
 */
export type CacheValue =
  | {
      kind: "APP_PAGE";
      html: string;
      rscData: Buffer | undefined;
      headers: Record<string, string | string[]> | undefined;
      postponed: string | undefined;
      status: number | undefined;
      segmentData: Map<string, Buffer> | undefined;
    }
  | {
      kind: "APP_ROUTE";
      body: Buffer;
      status: number;
      headers: Record<string, string | string[]>;
    }
  | {
      kind: "PAGES";
      html: string;
      pageData: Record<string, unknown>;
      status?: number;
      headers?: Record<string, string[]>;
    }
  | {
      kind: "FETCH";
      data: {
        headers: Record<string, string>;
        body: string;
        status: number;
        url: string;
      };
      revalidate: number | false;
    }
  | {
      kind: "REDIRECT";
      props: Record<string, unknown>;
    }
  | {
      kind: "IMAGE";
      etag: string;
      upstreamEtag: string;
      buffer: Buffer;
      extension: string;
      isMiss?: boolean;
      isStale?: boolean;
    };

/**
 * Lifespan parameters for cache entries
 * All time values are in SECONDS (not milliseconds)
 */
export interface LifespanParameters {
  /**
   * Timestamp when entry was last modified (seconds since epoch)
   */
  lastModifiedAt: number;

  /**
   * Timestamp when entry becomes stale (seconds since epoch)
   */
  staleAt: number;

  /**
   * Timestamp when entry expires (seconds since epoch)
   */
  expireAt: number;

  /**
   * Age in seconds until entry becomes stale
   */
  staleAge: number;

  /**
   * Age in seconds until entry expires
   */
  expireAge: number;

  /**
   * Original revalidate value from Next.js
   */
  revalidate: number | false | undefined;
}

/**
 * Lifetime Next.js gives a page or route handler entry (`ctx.cacheControl`)
 * All time values are in SECONDS
 */
export interface CacheControl {
  /**
   * Seconds after which the entry is stale and regenerated in the background,
   * or false to never revalidate on time
   */
  revalidate?: number | false;

  /**
   * Seconds after which the entry may no longer be served stale
   */
  expire?: number;
}

/**
 * Second argument of `revalidateTag` in Next.js 16: with durations, tagged
 * entries become stale now and expire after `expire` seconds; without, they
 * expire now
 */
export interface RevalidateTagDurations {
  expire?: number;
}

/**
 * Internal cache handler value with metadata
 * This is what handlers store internally
 */
export interface CacheHandlerValue {
  /**
   * Timestamp of last modification (milliseconds since epoch)
   */
  lastModified: number;

  /**
   * Lifespan/TTL parameters (null means no expiration)
   */
  lifespan: LifespanParameters | null;

  /**
   * Tags for cache invalidation (both explicit and implicit)
   */
  tags: readonly string[];

  /**
   * The actual cache value
   */
  value: CacheValue;

  /**
   * Lifetime Next.js gave the entry, returned from get() so any instance can
   * serve it with that lifetime (absent on entries from older versions)
   */
  cacheControl?: CacheControl;
}

/**
 * Context provided when setting cache entries
 * Next.js 16 passes `tags` for fetch entries and `cacheControl` for pages and
 * route handlers, whose tags are in the `x-next-cache-tags` header instead
 */
export interface CacheHandlerContext {
  /**
   * Tags for cache invalidation (fetch and unstable_cache entries)
   */
  tags?: string[];

  /**
   * Lifetime of a page or route handler entry
   */
  cacheControl?: CacheControl;

  /**
   * Revalidation period in seconds, or false to disable
   * (for callers that predate `cacheControl`)
   */
  revalidate?: number | false;

  /**
   * Soft tags (for Next.js internal use)
   */
  softTags?: string[];

  /**
   * True for fetch and unstable_cache entries
   */
  fetchCache?: boolean;
  fetchUrl?: string;
  fetchIdx?: number;
  isImplicitBuildTimeCache?: boolean;
  isRoutePPREnabled?: boolean;
  isFallback?: boolean;
}

/**
 * Context passed to get() method
 */
export interface CacheHandlerGetMeta {
  /**
   * Kind of entry being read ("FETCH", "APP_PAGE", "APP_ROUTE", "PAGES")
   */
  kind?: string;

  /**
   * Tags of the fetch being read
   */
  tags?: string[];

  /**
   * Implicit (path) tags of the current request, for fetch reads
   */
  softTags?: string[];

  /**
   * Implicit tags (system-generated) for this request
   * @deprecated Next.js 16 passes these as `softTags`
   */
  implicitTags?: string[];

  /**
   * Revalidate period of the fetch being read
   */
  revalidate?: number | false;

  fetchUrl?: string;
  fetchIdx?: number;
  isRoutePPREnabled?: boolean;
  isFallback?: boolean;
}

/**
 * Return type for cache handler get() method
 * Matches Next.js CacheHandlerValue structure
 */
export interface CacheHandlerGetResult {
  /**
   * The actual cache value (APP_PAGE, APP_ROUTE, PAGES, FETCH, REDIRECT, or IMAGE)
   */
  value: CacheValue | null;

  /**
   * Timestamp of last modification (milliseconds since epoch)
   */
  lastModified?: number;

  /**
   * Age of the cache entry in milliseconds
   */
  age?: number;

  /**
   * Lifetime Next.js gave the entry when it was stored
   */
  cacheControl?: CacheControl;

  /**
   * Cache state metadata (for debugging)
   */
  cacheState?: string;
}

/**
 * Cache handler interface that must be implemented
 */
export interface CacheHandler {
  /**
   * Handler name (for debugging/logging)
   */
  name: string;

  /**
   * Get a cache entry by key
   * Returns an object with the cache value and metadata
   */
  get(key: string, meta?: CacheHandlerGetMeta): Promise<CacheHandlerGetResult | null>;

  /**
   * Set a cache entry
   */
  set(key: string, value: CacheValue, context?: CacheHandlerContext): Promise<void>;

  /**
   * Revalidate cache entries by tag
   * @param tags - Cache tag, or tags, to revalidate (Next.js 16 passes an array)
   * @param durations - With durations, entries become stale now and expire
   *   after `durations.expire` seconds; without, they expire now
   */
  revalidateTag(
    tags: string | string[],
    durations?: RevalidateTagDurations | string,
  ): Promise<void>;

  /**
   * Delete a cache entry by key (optional)
   */
  delete?(key: string): Promise<void>;
}

/**
 * Cache handler constructor parameters
 */
export interface CacheHandlerOptions {
  /**
   * Next.js configuration
   */
  _appDir?: string;
  _pagesDir?: string;
  _requestHeaders?: Record<string, string>;
  flushToDisk?: boolean;
  experimental?: {
    ppr?: boolean;
  };
}
